) ?></small><small data-module-storage-conversion aria-live="polite"></small></label></div><div class="form-grid" data-module-quantity-fields><?php foreach(['min_qty'=>'Mindestmenge','max_qty'=>'Höchstmenge','default_qty'=>'Vorauswahl','sort_order'=>'Reihenfolge'] as $key=>$name): ?><label class="field"><span><?= $name ?></span><input type="number" name="<?= $key ?>" min="0" step="1" <?= $key==='sort_order'?'max="9999"':'' ?> <?= $key==='max_qty'?'placeholder="Unbegrenzt"':'required' ?> value="<?= $key==='unit_value'?e($_SERVER['REQUEST_METHOD']==='POST'?($_POST['unit_value']??1):module_display_step($m)):($key==='max_qty' && !(int)$m[$key]?'':e($m[$key])) ?>"><?php if($key==='min_qty'): ?><small>0 = optionales Zusatzmodul. Die Mengen zählen Moduleinheiten.</small><?php elseif($key==='default_qty'): ?><small data-module-quantity-status aria-live="polite">Die Vorauswahl muss mindestens der Mindestmenge entsprechen.</small><?php elseif($key==='max_qty'): ?><small>Leer lassen oder 0 eingeben = unbegrenzt.</small><?php endif ?></label><?php endforeach ?></div><label class="checkbox-field"><input type="checkbox" name="active" <?= $m['active']?'checked':'' ?>><span>Modul für Kunden zur Auswahl anbieten.</span></label><button class="button button-teal">Modul speichern</button></form></section><?php endif ?>
